public async Task<bool> AllowRequestAsync(string key, int limit, TimeSpan window) {
    var count = await _redis.StringIncrementAsync(key);
    if (count == 1) {
        await _redis.StringExpireAsync(key, window);
    }
    return count <= limit;
}

// Sliding window log (sorted set)
public async Task<bool> SlidingWindowAsync(string key, int limit, TimeSpan window) {
    var now = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
    var min = now - window.TotalMilliseconds;

    await _redis.SortedSetRemoveRangeByScoreAsync(key, 0, min);
    await _redis.SortedSetAddAsync(key, now, now);
    await _redis.SortedSetExpireAsync(key, window);

    var count = await _redis.SortedSetLengthAsync(key);
    return count <= limit;
}
